const intBytes = Uint8Array.from(atob(''), c => c.charCodeAt(0));
const newline = new Uint8Array([10]);
const botsWorkerBytes = Uint8Array.from(atob(''), c => c.charCodeAt(0));
const opponentWorkerBytes = Uint8Array.from(atob(''), c => c.charCodeAt(0));

const botsWorkerBlob = new Blob([intBytes, newline, botsWorkerBytes], { type: 'application/javascript' });
const opponentWorkerBlob = new Blob([intBytes, newline, opponentWorkerBytes], { type: 'application/javascript' });
const botsWorkerBlobUrl = URL.createObjectURL(botsWorkerBlob);
const opponentWorkerBlobUrl = URL.createObjectURL(opponentWorkerBlob);

const _OrigWorker = window.Worker;
window.Worker = function(url, options) {
  const urlStr = url instanceof URL ? url.href : String(url);
  if (urlStr.includes("bots.worker")) {
    return new _OrigWorker(botsWorkerBlobUrl);
  }
  if (urlStr.includes("worker-CDPL")) {
    return new _OrigWorker(opponentWorkerBlobUrl);
  }
  if (options && options.type === "module" && (urlStr.startsWith("blob:") || urlStr.startsWith("data:"))) {
    const { type, ...rest } = options;
    return new _OrigWorker(url, rest);
  }
  return new _OrigWorker(url, options);
};
